mapper.select:
SELECT AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, SDV.VALUE_NAME AS PAYMENT_SIGN_NAME, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, DATE_FORMAT(AC.PAYMENT_TIME, '%Y-%m-%d') AS PAYMENT_TIME_GROUPING_KEY FROM account_cost AC LEFT JOIN SYS_DICT_VALUE SDV ON SDV.DICT_KEY = 'PAYMENT_SIGN' WHERE 1=1 AND AC.LOGIC_DEL = 0
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
GROUP BY AC.PAYMENT_TIME, AC.CREATE_TIME ORDER BY AC.PAYMENT_TIME DESC, AC.CREATE_TIME ASC

SELECT SDV.VALUE AS COST_TYPE, SUM(AC.OUTLAY) AS OUTLAY FROM account_cost AC LEFT JOIN SYS_DICT_VALUE SDV ON SDV.DICT_KEY = 'ACCOUNT_COST_TYPE' AND SDV.VALUE_NAME = AC.COST_TYPE WHERE 1=1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
GROUP BY AC.COST_TYPE

SELECT
AC.ID,
AC.CREATE_TIME,
AC.MODIFY_TIME,
AC.LOGIC_DEL,
AC.REC_VER,
AC.TENANT_ID,
AC.COST_DESC,
AC.OUTLAY,
AC.COST_TYPE,
AC.PAYMENT_SIGN,
AC.PAYMENT_TIME,
AC.ICON,
AC.REMARK,
su.NICK_NAME AS USER_NAME
FROM account_cost AC
LEFT JOIN sys_user su on ac.USER_ID = su.ID
WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.USER_ID = #{accountCost.userId}
AND AC.TENANT_ID = #{accountCost.tenantId}
OR AC.ID IN (
SELECT ACU.COST_ID
FROM account_cost_user ACU
WHERE 1=1
AND ACU.USER_ID = #{accountCost.userId}
)

    AND AC.ID = #{accountCost.id}


    AND AC.COST_DESC = #{accountCost.costDesc}


    AND AC.REMARK = #{accountCost.remark}


    AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}


    AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}


    AND AC.PAYMENT_TIME >= #{accountCost.paymentTimeFrom}
    AND AC.PAYMENT_TIME <= #{accountCost.paymentTimeTo}

ORDER BY AC.PAYMENT_TIME DESC, AC.MODIFY_TIME DESC

SELECT AC.ID, AC.CREATOR, AC.CREATE_TIME, AC.MODIFIER, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.BUILD_IN, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, SU.ID AS SU_ID, SU.USER_NAME AS USER_NAME, SU.NICK_NAME AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID LEFT JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID = #{accountCost.userId} OR SU.ID IN ( SELECT ACU.USER_ID FROM account_cost_user ACU WHERE 1 = 1
AND ACU.COST_ID = #{accountCost.id}
)
AND ac.ID = #{accountCost.id}
